  private unsupportedProtocol?: string;

  constructor(options: SidecarOptions) {
    this.app = options.app;
    this.write = options.write;
    const config = this.app.getConfig();
    this.mode = options.mode ?? config.approvalMode ?? (config.readOnly ? "read-only" : config.fullAccess ? "auto" : "review");
    this.app.getAgent().setApprovalMode(this.mode);
    this.onShutdown = options.onShutdown ?? (() => {});
    this.resume = options.resume;
    this.fullHistoryReplay = options.fullHistoryReplay ?? false;
    switch (command.type) {
      case "initialize":
        this.initialize(command.id, command.protocol_min ?? PROTOCOL_VERSION, command.protocol_max ?? PROTOCOL_VERSION, command.experimental === true);
        return;
      case "prompt.submit":
        this.submit(command.id, command.text);
        return;
      case "steer":
        this.steer(command.id, command.text);
        return;
      case "cancel":
        this.cancel();
        return;
      case "approve":
        this.resolveApproval(command.id, true, command.always);
        return;
      case "deny":
        this.resolveApproval(command.id, false, false);
        return;
      case "answer":
        // Bound to the decision by id; consumed when a turn reaches it (an unresolved steering conflict: at the next
        // turn's start). An id no turn asked about is simply never consumed.
        this.app.getAgent().setOperatorAnswers(new Map([[command.question, command.option]]));
        this.emit({ type: "notice", text: `Answer recorded for question ${command.question}: ${command.option}. It applies when the next turn reaches that decision.` });
        return;
      case "checkpoint.choice":
        this.resolveCheckpointChoice(command.id, command.choice);
        return;
      case "slash":
        this.slash(command.id, command.command, command.args);
        return;
      case "tool.detail":
      case "receipt":
        try {
          if (command.type === "tool.detail") this.toolDetail(command.id, command.evidence);
          else this.emit({ type: "receipt", id: command.id, sections: this.receipt() });
        } catch (err) {
          const message = errorText(err);
          this.emit({ type: "error", id: command.id, code: "INTERNAL", message });
        }
        return;
    pages.forEach((page, index) => this.emit(eventFor(index, pages.length, page)));
  }

  private shutdown(): Promise<void> {
    for (const signIn of this.signIns.values()) signIn.cancel();
    this.signIns.clear();
    for (const list of this.modelLists.values()) list.abort();
    this.shutdownPromise ??= (async () => {
      this.startupProbeAbort.abort();
      this.turnAbort?.abort(new Error("sidecar shutdown"));
      await this.idle();
      this.app.shutdown();
      this.onShutdown();
    })();
    return this.shutdownPromise;
  }

